exercises.starter_code:
#include <stdio.h>

static void modify(int *p) { }

int main(void) {
    // modify(&num);
    return 0;
}

exercises.solution:
#include <stdio.h>

static void modify(int *p) { *p = *p * 2; }

int main(void) {
    int num = 5;
    modify(&num);
    printf("%d\n", num);
    return 0;
}

exercises.starter_code:
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    // malloc int, set 99
    return 0;
}

exercises.solution:
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *ptr = malloc(sizeof *ptr);
    *ptr = 99;
    printf("%d\n", *ptr);
    free(ptr);
    return 0;
}

