exercises.starter_code:
#include <stdio.h>

static void swap(int *a, int *b) { }

int main(void) {
    // swap(&x, &y);
    return 0;
}

exercises.solution:
#include <stdio.h>

static void swap(int *a, int *b) {
    int t = *a; *a = *b; *b = t;
}

int main(void) {
    int x = 5, y = 10;
    swap(&x, &y);
    printf("%d %d\n", x, y);
    return 0;
}
